// to materialize COMMANDS.md from the real artifacts.toml, then delete.
#[path = "../src/registry.rs"]
mod registry;

fn main() {
    let repo_root = registry::resolve_repo_root().expect("repo root resolves");
    let text = std::fs::read_to_string(repo_root.join("tools/install/artifacts.toml"))
        .expect("artifacts.toml is readable");
    let parsed = registry::parse_registry_v2(&text).expect("artifacts.toml parses under v2 schema");
    let rendered = registry::render_catalog(&parsed);
    std::fs::write(repo_root.join("COMMANDS.md"), rendered).expect("COMMANDS.md is writable");
}

